output:
{
  "world_id": "wld_mariana_six",
  "name": "Mariana Six",
  "description": "Eleven kilometers beneath the Atlantic, the corporate colony Mariana Six farms bio-engineered leviathans for the rare enzymes in their glands. The setting is biopunk and the tone is tense. Every corridor is wet, pressurized and lit by bioluminescent tissue grown for profit. The colony's largest leviathan, Mother Tithe, has developed a contagious sentience. It is turning the station's workers into a hive mind, and the people left in charge are three rival department heads. Each answers to different shareholders. One wants to save the station, one wants to secure the creature, and one wants to seal off the infection and write the losses off. Pressure, quarantine and quarterly targets all close in at once.",
  "locations": [
    {
      "id": "loc_brine_gate",
      "name": "Brine Gate",
      "description": "The colony's only dock and decompression lock. Supply sleds arrive here every ninety days. It is the sole route to the surface, and whoever controls its seals controls who leaves."
    },
    {
      "id": "loc_helix_decks",
      "name": "Helix Decks",
      "description": "A spiral of crew habitats grown from living coral-polymer. The walls pulse faintly. Workers here are the first to hum in unison, and they stop speaking aloud."
    },
    {
      "id": "loc_trench_pens",
      "name": "Trench Pens",
      "description": "Flooded cavern enclosures anchored to the trench wall. Juvenile and adult leviathans are bred and milked here under sonar-guided restraints. Mother Tithe, the largest, lives in the deepest pen."
    },
    {
      "id": "loc_enzyme_foundry",
      "name": "Enzyme Foundry",
      "description": "A heat-lit processing plant where leviathan secretions are distilled into patented enzymes. It holds the colony's most valuable stockpile and its only full cold-storage vaults."
    },
    {
      "id": "loc_ledger_atrium",
      "name": "Ledger Atrium",
      "description": "A glass-walled executive ring where the department heads meet and shareholder feeds are received. Live valuation screens show the creature's worth and the station's losses side by side."
    }
  ],
  "factions": [
    {
      "id": "fac_vitaforge_husbandry",
      "name": "Vitaforge Husbandry",
      "description": "The breeding and animal-care division. Its head, Dr. Ilse Varga, believes the leviathan's sentience can be understood and that the station's survival depends on communicating with it. Her shareholders prize the long-term breeding stock.",
      "location_ids": ["loc_trench_pens", "loc_helix_decks"]
    },
    {
      "id": "fac_halcyon_extraction",
      "name": "Halcyon Extraction",
      "description": "The enzyme production and sales division. Its head, Corwin Adeyemi, wants Mother Tithe captured intact and her glands preserved for the enzyme patents, whatever happens to the workers.",
      "location_ids": ["loc_enzyme_foundry", "loc_trench_pens"]
    },
    {
      "id": "fac_meridian_assurance",
      "name": "Meridian Assurance",
      "description": "The security and risk division. Its head, Tamsin Okoro, answers to insurers and favors total quarantine, sealing the station and sacrificing the infected to protect the corporation's liability position.",
      "location_ids": ["loc_brine_gate", "loc_ledger_atrium"]
    },
    {
      "id": "fac_choir",
      "name": "The Choir",
      "description": "The growing hive mind of infected workers. They move and speak as one, guided by Mother Tithe's signals, and want to open the pens and release the leviathans into the open ocean.",
      "location_ids": ["loc_helix_decks", "loc_trench_pens"]
    }
  ],
  "rules": [
    {
      "id": "rul_pressure_limits",
      "statement": "Unprotected humans cannot survive outside the colony's pressure hulls; any breach is lethal within seconds.",
      "category": "physics"
    },
    {
      "id": "rul_sentience_contagion",
      "statement": "The leviathan's sentience spreads through a waterborne pheromone and through direct contact with its secretions; airborne spread is not possible, but recycled station water carries it.",
      "category": "technology"
    },
    {
      "id": "rul_no_supernatural",
      "statement": "Every phenomenon in the colony has a biological or engineered cause; nothing operates outside natural law.",
      "category": "physics"
    },
    {
      "id": "rul_ninety_day_resupply",
      "statement": "Surface resupply and evacuation can occur only through Brine Gate, and only when a sled is docked, roughly every ninety days.",
      "category": "technology"
    },
    {
      "id": "rul_shareholder_mandate",
      "statement": "Each department head is legally bound to act in their own shareholders' interest, and any contract breach triggers personal liability.",
      "category": "social"
    },
    {
      "id": "rul_hive_proximity",
      "statement": "Infected workers share perception only within hearing range of the hum, so distance and isolation weaken the hive mind.",
      "category": "other"
    }
  ],
  "history": [
    {
      "id": "evt_founding",
      "name": "Founding of Mariana Six",
      "description": "Three corporations joined to build the colony around a trench vent rich in enzyme-bearing marine life.",
      "era": "Founding Era",
      "location_ids": ["loc_brine_gate", "loc_enzyme_foundry"]
    },
    {
      "id": "evt_first_leviathan",
      "name": "The First Leviathan Hatching",
      "description": "Vitaforge engineers cultured the first bio-engineered leviathan, proving that large-scale enzyme milking was profitable.",
      "era": "Founding Era",
      "location_ids": ["loc_trench_pens"]
    },
    {
      "id": "evt_tithe_breeding",
      "name": "Breeding of Mother Tithe",
      "description": "Husbandry spliced neural genes into a record-sized leviathan to increase enzyme yield, an experiment that unknowingly raised her cognition.",
      "era": "Expansion Era",
      "location_ids": ["loc_trench_pens"]
    },
    {
      "id": "evt_audit_dispute",
      "name": "The Quarterly Audit Dispute",
      "description": "Halcyon and Meridian clashed over output quotas and safety shutdowns, leaving the division heads deeply distrustful of one another.",
      "era": "Expansion Era",
      "location_ids": ["loc_ledger_atrium"]
    },
    {
      "id": "evt_first_hum",
      "name": "The First Hum",
      "description": "A night-shift crew on the Helix Decks began humming a single tone and working in perfect sync, the first sign of infection.",
      "era": "Outbreak",
      "location_ids": ["loc_helix_decks"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_save_or_secure",
      "name": "Save the Station or Secure the Creature",
      "description": "Vitaforge wants to preserve the station by understanding the creature, Halcyon wants to capture it intact for its patents, and Meridian wants to seal everything off to limit losses. Each plan sacrifices what another values most.",
      "faction_ids": ["fac_vitaforge_husbandry", "fac_halcyon_extraction", "fac_meridian_assurance"]
    },
    {
      "id": "cnf_quarantine_vs_choir",
      "name": "Quarantine Against the Choir",
      "description": "Meridian's sealed-hull quarantine would trap the infected workers inside with the stockpile and the pens, and the Choir will fight to open the pens before that happens.",
      "faction_ids": ["fac_meridian_assurance", "fac_choir"]
    },
    {
      "id": "cnf_patent_vs_release",
      "name": "Patents Against Release",
      "description": "Halcyon's plan to capture Mother Tithe collides with the Choir's goal of freeing the leviathans, and with Vitaforge's wish to study her alive.",
      "faction_ids": ["fac_halcyon_extraction", "fac_choir", "fac_vitaforge_husbandry"]
    }
  ]
}
